{:file "cljs/core.cljs", :line 138, :column 1, :end-line 144, :end-column 14, :dynamic true, :doc "When set to logical true, objects will be printed in a way that preserves
  their type when read in later.

  Defaults to false.", :arglists ()}

{:file "cljs/core.cljs", :line 130, :column 1, :end-line 136, :end-column 15, :dynamic true, :doc "If set to logical true, when printing an object, its metadata will also
  be printed in a form that can be read back by the reader.

  Defaults to false.", :arglists ()}

{:file "cljs/core.cljs", :line 146, :column 1, :end-line 152, :end-column 25, :dynamic true, :doc "*print-namespace-maps* controls whether the printer will print
  namespace map literal syntax.

  Defaults to false, but the REPL binds it to true.", :arglists ()}

{:file "cljs/core.cljs", :line 122, :column 1, :end-line 128, :end-column 19, :dynamic true, :doc "When set to logical false, strings and characters will be printed with
  non-alphanumeric characters converted to the appropriate escape sequences.

  Defaults to true", :arglists ()}

{:file "cljs/core.cljs", :line 10885, :column 1, :end-line 10885, :end-column 18, :doc "Atomically sets the metadata for a namespace/var/ref/agent/atom to be:

  (apply f its-current-meta args)

  f must be free of side-effects", :top-fn {:variadic? true, :fixed-arity 2, :max-fixed-arity 2, :method-params [(iref f args)], :arglists ([iref f & args]), :arglists-meta (nil)}, :arglists ([iref f & args])}

{:file "cljs/core.cljs", :line 2462, :column 1, :end-line 2462, :end-column 25, :tag boolean, :doc "Returns true if key is present in the given collection, otherwise
  returns false.  Note that for numerically indexed collections like
  vectors and arrays, this tests if the numeric key is within the
  range of indexes. 'contains?' operates constant or logarithmic time;
  it will not perform a linear search for a value.  See also 'some'.", :arglists ([coll v])}

{:file "cljs/core.cljs", :line 12109, :column 1, :end-line 12109, :end-column 18, :doc "m f => {(f k) v ...}
  Given a map m and a function f of 1-argument, returns a new map whose
  keys are the result of applying f to the keys of m, mapped to the
  corresponding values of m.
  f must return a unique key for each key of m, else the behavior is undefined.", :added "1.11", :arglists ([m f])}
